using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Net;using System.Net.Sockets;using System.Text;using System.Threading;using System.Windows.Forms;
namespace SenseBridge {
public sealed class AudioEventRule {public string Name{get;set;}public int Id{get;set;}public int Frequency{get;set;}public int Samples{get;set;}public string Category{get;set;}public string TriggerAction{get;set;}}
public sealed class TriggerStateRule {public string Fsm{get;set;}public string State{get;set;}public string Action{get;set;}public int Milliseconds{get;set;}public int Power{get;set;}}
public sealed class UnityAudioPack {public string ActorComponent{get;set;}public List<TriggerStateRule> StateRules{get;set;}public string InputComponent{get;set;}public string ActionSetField{get;set;}public string PackId{get;set;}public string Executable{get;set;}public string AssemblySha256{get;set;}public List<AudioEventRule> Rules{get;set;}}
public static class EventPacks {
 public static bool Is(GameProfile g){return g!=null&&g.Adapter=="unity-audio-v1";}
 public static bool Dedicated(GameProfile g){return Store.Supported(g)||Is(g);}
 public static string DirectoryFor(string root,string id){if(string.IsNullOrEmpty(id)||id.Length>80||id.Any(c=>!(c>='a'&&c<='z'||c>='0'&&c<='9'||c=='-')))throw new InvalidDataException("Invalid pack ID");return Path.Combine(root,"packs",id);}
 public static string Config(string root,GameProfile g){return Path.Combine(DirectoryFor(root,g.PackId),"session.ini");}
 public static void Validate(GamePreset p){
  var u=p.Unity;if(p.Version!=2||u==null)throw new InvalidDataException("Unity audio pack v2 required");DirectoryFor(".",u.PackId);
  foreach(var text in new[]{u.InputComponent,u.ActionSetField}.Concat(u.Rules==null?new string[0]:u.Rules.Select(r=>r==null?null:r.TriggerAction)))if(!string.IsNullOrEmpty(text)&&(text.Length>100||text.Any(c=>!(char.IsLetterOrDigit(c)||c=='_'||c=='.'))))throw new InvalidDataException("Invalid input binding identifier");
  if(string.IsNullOrWhiteSpace(u.Executable)||Path.GetFileName(u.Executable)!=u.Executable||u.Executable.IndexOfAny(Path.GetInvalidFileNameChars())>=0||!u.Executable.EndsWith(".exe",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Invalid executable name");
  if(u.AssemblySha256==null||u.AssemblySha256.Length!=64||u.AssemblySha256.Any(c=>!Uri.IsHexDigit(c)))throw new InvalidDataException("Game assembly hash required");
  if(u.StateRules!=null){if(u.StateRules.Count>512||string.IsNullOrEmpty(u.ActorComponent)||u.ActorComponent.Length>100||u.ActorComponent.Any(c=>!char.IsLetterOrDigit(c)&&c!='_'))throw new InvalidDataException("Invalid state owner");var unique=new HashSet<string>();foreach(var state in u.StateRules){if(state==null||new[]{state.Fsm,state.State,state.Action}.Any(v=>string.IsNullOrWhiteSpace(v)||v.Length>100||v.Any(char.IsControl))||state.Action.Any(c=>!char.IsLetterOrDigit(c)&&c!='_')||state.Milliseconds<30||state.Milliseconds>350||state.Power<1||state.Power>100||!unique.Add(state.Fsm+"\t"+state.State))throw new InvalidDataException("Invalid trigger state rule");}}
  if(u.Rules==null||u.Rules.Count<1||u.Rules.Count>1000||u.Rules.Select(r=>r==null?null:r.Name).Distinct().Count()!=u.Rules.Count)throw new InvalidDataException("Invalid sound rules");
  for(int i=0;i<u.Rules.Count;i++){var r=u.Rules[i];if(r==null||r.Id!=i||string.IsNullOrWhiteSpace(r.Name)||r.Name.Length>200||r.Name.Any(char.IsControl)||r.Frequency<8000||r.Frequency>192000||r.Samples<1||r.Samples>r.Frequency*2)throw new InvalidDataException("Sound identity bounds");}
  if(!string.IsNullOrEmpty(p.AdapterSha256)||p.Assets==null||p.Assets.Count!=1||p.Assets[0]==null||p.Assets[0].Name!="events.bin"||p.Assets[0].Data==null||p.Assets[0].Data.Length>90*1024*1024)throw new InvalidDataException("Event bank required");
  byte[] b=Convert.FromBase64String(p.Assets[0].Data);if(b.Length>64*1024*1024||Presets.Hash(b)!=p.Assets[0].Sha256)throw new InvalidDataException("Event bank hash");
  using(var r=new BinaryReader(new MemoryStream(b))){if(Encoding.ASCII.GetString(r.ReadBytes(8))!="SBEVENT1"||r.ReadUInt32()!=u.Rules.Count)throw new InvalidDataException("Event bank header");foreach(var rule in u.Rules){uint h=r.ReadUInt32(),s=r.ReadUInt32(),t=r.ReadUInt32();if(h<1||h>96000||s>96000||t>3||r.BaseStream.Length-r.BaseStream.Position<(h+s)*2L)throw new InvalidDataException("Event bank bounds");for(int i=0;i<h;i++){short v=r.ReadInt16();if(v>4588||v< -4588)throw new InvalidDataException("Haptic amplitude limit");}r.BaseStream.Position+=s*2;}if(r.BaseStream.Position!=r.BaseStream.Length)throw new InvalidDataException("Event bank trailing data");}
 }
 public static UnityAudioPack Manifest(string root,GameProfile g){return Store.Json.Deserialize<UnityAudioPack>(File.ReadAllText(Path.Combine(DirectoryFor(root,g.PackId),"manifest.json")));}
 public static string Executable(GameProfile g,UnityAudioPack u){return !string.IsNullOrEmpty(g.EngineExecutable)?g.EngineExecutable:Path.Combine(g.InstallDirectory??"",u.Executable);}
 // Only application-supplied runtime files are installed; imported JSON cannot supply executable code.
 public static void Install(string root,GameProfile g){
  var u=Manifest(root,g);string exe=Executable(g,u);if(!File.Exists(exe))throw new FileNotFoundException("Select the game executable first",exe);string game=Path.GetDirectoryName(Path.GetFullPath(exe));
  string assembly=Path.Combine(game,Path.GetFileNameWithoutExtension(exe)+"_Data","Managed","Assembly-CSharp.dll");if(!File.Exists(assembly)||Presets.Hash(File.ReadAllBytes(assembly))!=u.AssemblySha256)throw new InvalidDataException("Game build differs from the imported pack");
  foreach(var p in Process.GetProcessesByName(Path.GetFileNameWithoutExtension(exe))){using(p){try{if(string.Equals(p.MainModule.FileName,exe,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Close the game normally before installing its audio-event connection.");}catch(System.ComponentModel.Win32Exception){throw new InvalidOperationException("Cannot verify game process; close it before connecting.");}}}
  string runtime=Path.Combine(root,"UnityRuntime");if(!Directory.Exists(runtime))throw new FileNotFoundException("Unity audio runtime is missing from this build");
  var files=Directory.GetFiles(runtime,"*",SearchOption.AllDirectories);if(files.Length==0)throw new InvalidDataException("Empty Unity runtime");
  var writes=new Dictionary<string,byte[]>();foreach(string file in files){string rel=file.Substring(runtime.Length+1);string dest=Path.Combine(game,rel);byte[] bytes=File.ReadAllBytes(file);if(File.Exists(dest)&&!File.ReadAllBytes(dest).SequenceEqual(bytes))throw new InvalidOperationException("Existing mod loader or bridge differs: "+rel+". No files were replaced.");writes[dest]=bytes;}
  string link=Path.Combine(game,@"BepInEx\plugins\SenseBridge\bridge-link.ini");writes[link]=Encoding.UTF8.GetBytes("config="+Config(root,g)+"\n");var made=new List<string>();
  try{foreach(var w in writes){Directory.CreateDirectory(Path.GetDirectoryName(w.Key));if(!File.Exists(w.Key)){File.WriteAllBytes(w.Key,w.Value);made.Add(w.Key);}else if(w.Key==link)File.WriteAllBytes(w.Key,w.Value);}}catch{foreach(var f in made)File.Delete(f);throw;}
 }
 static Process worker;static string current;static volatile bool ready;static string last;
 public static bool Running {get{try{return worker!=null&&!worker.HasExited;}catch{return false;}}}
 public static void Stop(){if(current!=null){var d=Store.ReadIni(current);d["enabled"]="0";d["token"]="";Store.WriteIni(current,d);}if(Running&&!worker.WaitForExit(2500))throw new IOException("Waiting for event engine to release controller");if(worker!=null){worker.Dispose();worker=null;}current=null;}
 public static void Apply(GameProfile g){var d=Store.ReadIni(Config(Store.Root,g));d["haptics"]=g.UseHaptics?"1":"0";d["triggers"]=g.UseTriggers?"1":"0";d["speaker"]=g.UseSpeaker?"1":"0";Store.WriteIni(Config(Store.Root,g),d);}
 public static void Start(GameProfile g,Process game){
  Stop();var u=Manifest(Store.Root,g);string exe=game.MainModule.FileName,gameDir=Path.GetDirectoryName(exe);string link=Path.Combine(gameDir,@"BepInEx\plugins\SenseBridge\bridge-link.ini");
  if(!File.Exists(link))throw new InvalidOperationException("Install the imported pack connection using Change executable, then restart the game.");
  string assembly=Path.Combine(gameDir,Path.GetFileNameWithoutExtension(exe)+"_Data","Managed","Assembly-CSharp.dll");if(Presets.Hash(File.ReadAllBytes(assembly))!=u.AssemblySha256)throw new InvalidDataException("Game build differs from pack");
  current=Config(Store.Root,g);var d=Store.ReadIni(current);d["enabled"]="1";d["token"]=Guid.NewGuid().ToString("N");using(var socket=new UdpClient(new IPEndPoint(IPAddress.Loopback,0))){d["port"]=((IPEndPoint)socket.Client.LocalEndPoint).Port.ToString();}
  d["bank"]=Path.Combine(DirectoryFor(Store.Root,g.PackId),"events.bin");d["rules"]=Path.Combine(DirectoryFor(Store.Root,g.PackId),"rules.tsv");d["assembly_sha256"]=u.AssemblySha256;d["actor_component"]=u.ActorComponent??"";d["states"]=Path.Combine(DirectoryFor(Store.Root,g.PackId),"states.tsv");d["input_component"]=u.InputComponent??"";d["action_set_field"]=u.ActionSetField??"";Store.WriteIni(current,d);Store.Atomic(link,"config="+current+"\n");
  var info=GenericEngine.Info("\""+current+"\" "+Process.GetCurrentProcess().Id+" "+game.Id);info.FileName=Path.Combine(Store.Root,"SenseBridge.Events.exe");ready=false;last="Event engine startup";worker=new Process{StartInfo=info};worker.OutputDataReceived+=delegate(object s,DataReceivedEventArgs e){if(e.Data!=null){last=e.Data;if(e.Data.StartsWith("READY |"))ready=true;}};worker.ErrorDataReceived+=delegate(object s,DataReceivedEventArgs e){if(e.Data!=null)last=e.Data;};worker.Start();worker.BeginOutputReadLine();worker.BeginErrorReadLine();var until=DateTime.UtcNow.AddSeconds(5);while(!ready&&Running&&DateTime.UtcNow<until)Thread.Sleep(25);if(!ready){string error=last;Stop();throw new IOException(error);}
 }
}
sealed class EventDetailsForm:Form {
 public EventDetailsForm(GameProfile g,bool speaker){Text=L.T("상세 옵션");ClientSize=new Size(550,365);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(24,28,40);ForeColor=Color.WhiteSmoke;Font=new Font("Malgun Gothic",10);var path=EventPacks.Config(Store.Root,g);var d=Store.ReadIni(path);var label=new Label{Text=L.T(speaker?"스피커 음량":"햅틱 강도"),Bounds=new Rectangle(24,25,165,30)};var number=new ValueSlider(speaker?100:4,Store.Number(d,speaker?"speaker_volume":"gain",speaker?25:2,0,speaker?100:4),speaker?0:2,speaker?"%":""){Bounds=new Rectangle(200,20,320,68)};Controls.Add(label);Controls.Add(number);var left=new ValueSlider(8,Store.Number(d,"left_force",3,0,8),0,""){Bounds=new Rectangle(200,105,320,68),Visible=!speaker};var right=new ValueSlider(8,Store.Number(d,"right_force",3,0,8),0,""){Bounds=new Rectangle(200,190,320,68),Visible=!speaker};Controls.Add(left);Controls.Add(right);Controls.Add(new Label{Text=L.T("L2 저항"),Bounds=new Rectangle(24,105,165,30),Visible=!speaker});Controls.Add(new Label{Text=L.T("R2 저항"),Bounds=new Rectangle(24,190,165,30),Visible=!speaker});var save=new Button{Text=L.T("저장"),Bounds=new Rectangle(420,300,100,35)};save.Click+=delegate{var v=Store.ReadIni(path);v[speaker?"speaker_volume":"gain"]=number.Value.ToString(System.Globalization.CultureInfo.InvariantCulture);if(!speaker){v["left_force"]=left.Value.ToString();v["right_force"]=right.Value.ToString();}Store.WriteIni(path,v);Close();};Controls.Add(save);}
}
